await assert.rejects(
  build({
    root,
    configFile: false,
    logLevel: 'silent',
    plugins: [featureFlags({ source, expose: ['missingFlag'] })],
    build: { write: false },
  }),
  (error) => {
    const message = error instanceof Error ? error.message : String(error)
    return message.includes('missingFlag') && message.includes('flags.json')
  },
)

